import json, math
from pathlib import Path
base=json.load(open('data/ege_2027.json'))
T=[];Q=[]
def topic(n,form,alg,example,errors):
 t=next(x.copy() for x in base['topics'] if x['subject_code']=='math' and x['task_number']==n)
 t['theory']=f'Авторская памятка по проекту ЕГЭ-2027.\n\nФормулы и условия\n{form}\n\nАлгоритмы прототипов\n{alg}\n\nРазобранный пример\n{example}\n\nПроверка и ошибки\n{errors}\n\nМатериал охватывает основные приёмы, но не исчерпывает возможные КИМ. Задания авторские, не официальный вариант ФИПИ.'
 t['practice_scope']='Развёрнутое решение · самопроверка' if n>=14 else 'Экзаменационные прототипы';T.append(t)
def q(n,proto,p,a,e):
 i=1+sum(x['task_number']==n for x in Q)
 if n>=14:e+='\n\nСамопроверка: записаны все ограничения и обоснованы преобразования; получен полный ответ на каждый пункт. Сверьте ключевые вычисления и выводы с решением. Это учебный ориентир, а не официальная балльная шкала ФИПИ.'
 Q.append(dict(id=f'math-full-2027-{n:02d}-{i}',subject_code='math',task_number=n,kind='self_check' if n>=14 else 'number',prompt=p,options=[],answer=str(a),explanation=e,prototype=proto))
def pack(n,rows):
 for row in rows:q(n,*row)
topic(1,'Треугольник: сумма углов 180°, S=ah/2=ab sin C/2=pr, a/sin A=2R, c²=a²+b²−2ab cos C. Биссектриса делит противоположную сторону в отношении прилежащих сторон. Средняя линия равна половине третьей стороны. Для подобных фигур S₁/S₂=k². Вписанный угол равен половине дуги, на которую опирается; радиус к касательной перпендикулярен ей. Для описанного четырёхугольника AB+CD=BC+AD=p.','Углы: отметьте дуги, параллельность, биссектрисы. Площади: найдите общую высоту или подобие. Окружность: соедините центр с точками касания; в прямоугольном треугольнике диаметр — гипотенуза. Трапеция: средняя линия (a+b)/2; площадь (a+b)h/2.','В треугольнике площади 80 средняя линия отсекает подобный треугольник с k=1/2. Его площадь 20, оставшаяся трапеция имеет площадь 60.','Высота перпендикулярна основанию; площадь меняется как квадрат коэффициента. Рисунок не заменяет доказательства. Отличайте центральный угол от вписанного.')
topic(2,'AB=(xB−xA;yB−yA); a·b=ax bx+ay by=|a||b|cos φ; |a|=√(ax²+ay²). Для ненулевых векторов перпендикулярность равносильна a·b=0, коллинеарность — ax by−ay bx=0. Проекция a на направление b равна (a·b)/|b|.','Координатная задача: сначала получите векторы как конец минус начало. Линейная комбинация: действия покоординатно, затем длина. Угол: вычислите произведение и обе длины. Параметр: составьте условие ортогональности или коллинеарности.','A=(−1;2), B=(3;5), значит AB=(4;3), |AB|=5. Для c=(3;−4) произведение 4·3+3·(−4)=0, поэтому AB⊥c.','Не путайте координаты точки и вектора. |a+b| обычно не равно |a|+|b|; a·b — число. Нулевой вектор не имеет определённого угла с другим вектором.')
topic(3,'Призма V=Sосн h; пирамида V=Sосн h/3. Цилиндр V=πr²h, Sбок=2πrh. Конус V=πr²h/3, Sбок=πrl, l²=r²+h² для прямого конуса. Шар V=4πr³/3, S=4πr². При подобии длины, площади, объёмы меняются в k, k², k³ раз.','Составное тело: разбейте на известные тела или вычтите полость. Сечение параллельно основанию пирамиды: найдите линейный коэффициент от вершины и возведите в куб для объёмов. Вращение прямоугольника: явно укажите ось. Пространственная диагональ параллелепипеда d²=a²+b²+c².','От пирамиды объёма 216 отсекли у вершины подобную пирамиду плоскостью на половине высоты. Её объём 216/8=27; оставшаяся часть 189.','Не используйте наклонное ребро вместо высоты. У сферы нет объёма оболочки; объём относится к шару. В отношениях сначала сокращайте π.')
topic(4,'Для конечных равновозможных исходов P(A)=m/n. Противоположное событие имеет вероятность 1−P(A). При выборе двух предметов без порядка всего C(n,2)=n(n−1)/2 пар. Частота не равна вероятности в конкретной небольшой серии.','Выбор предмета: считайте благоприятные и все исходы в одной модели. Кубики: различайте упорядоченные пары из 36 исходов и суммы, которые не равновозможны. Размещение: найдите число подходящих мест. Геометрическая вероятность: длина/длина или площадь/площадь только при равномерном выборе.','При двух бросках кубика сумма 9 получается в парах (3,6),(4,5),(5,4),(6,3): вероятность 4/36=1/9. Если просят десятичную дробь, в условии должны быть данные с конечным ответом.','Не считайте суммы кубиков равновероятными. При выборе без возвращения число оставшихся предметов уменьшается. Вероятность лежит между 0 и 1.')
topic(5,'P(A∪B)=P(A)+P(B)−P(A∩B). P(A∩B)=P(A)P(B|A). Независимость даёт P(A∩B)=P(A)P(B). Полная вероятность: P(A)=ΣP(Hᵢ)P(A|Hᵢ) для полной группы несовместных гипотез. Формула Байеса P(H|A)=P(H)P(A|H)/P(A). Бернулли: P(X=k)=C(n,k)pᵏ(1−p)ⁿ⁻ᵏ.','«Хотя бы один»: удобнее вычесть вероятность ни одного из 1. «Ровно один»: сложите несовместные случаи. Без возвращения: дерево с меняющимися знаменателями. Условная вероятность: сузьте пространство до выполненного условия. Смешанное производство: полная вероятность, затем при необходимости Байес.','Два независимых попадания имеют p₁=0,8,p₂=0,5. Ровно одно: 0,8·0,5+0,2·0,5=0,5; хотя бы одно: 1−0,2·0,5=0,9.','Независимость не следует из несовместности. Не перемножайте вероятности зависимых событий без условной вероятности. Сумма вероятностей ветвей одного узла равна 1.')
topic(6,'Дискретная случайная величина задана значениями xᵢ и вероятностями pᵢ≥0, Σpᵢ=1. E(X)=Σxᵢpᵢ; E(aX+b)=aE(X)+b. E(X+Y)=E(X)+E(Y) без требования независимости. Для числа успехов в n испытаниях E(X)=np. Если используется дисперсия: D(X)=E(X²)−E(X)².','Таблица: восстановите отсутствующую вероятность и сложите произведения. Выигрыш: вычтите цену участия из ожидаемой выплаты. Доход: учтите вероятности потерь. Повторы: используйте линейность ожидания. Оптимальный выбор: сравните именно ожидаемый чистый результат.','Выплаты 0,100,500 имеют вероятности 0,6;0,3;0,1. Средняя выплата 0+30+50=80. При цене билета 60 ожидаемый чистый выигрыш 20.','Ожидание может не быть возможным значением X. Не делите сумму выплат на число значений, если вероятности различны. Цена билета учитывается один раз на одну покупку.')
topic(7,'aˣ=aʸ ⇒ x=y при a>0,a≠1. logₐf(x)=b ⇒ f(x)=aᵇ при f(x)>0. √f(x)=g(x) ⇒ f=g² и g≥0. Дробь равна нулю, когда числитель нулевой, а знаменатель нет. Для квадратного уравнения D=b²−4ac.','Линейное/квадратное: упростите и решите. Рациональное: выпишите запрещённые значения. Степенное: приведите к одному основанию. Логарифмическое: запишите ОДЗ до преобразований. Радикальное: возведите в квадрат и проверьте корни. Тригонометрическое: учитывайте указанный промежуток.','√(2x+3)=x: x≥0; 2x+3=x² ⇒ x=3 или −1. Подходит только 3.','Возведение в квадрат может добавить корни. log(u+v) не равен log u+log v. Отрицательное основание нельзя произвольно возводить в дробную степень.')
topic(8,'aᵘaᵛ=aᵘ⁺ᵛ; (aᵘ)ᵛ=aᵘᵛ при корректных основаниях. √(a²)=|a|. logₐbc=logₐb+logₐc при b,c>0. sin²x+cos²x=1; sin2x=2sinx cosx; cos2x=2cos²x−1. Проценты: p%=p/100.','Радикалы: вынесите полный квадрат или домножьте на сопряжённое. Логарифмы: объединяйте только при общей основе и положительных аргументах. Тригонометрия: найдите четверть, затем знак. Буквенные выражения: сократите с сохранением исходных ограничений.','При x<0 выражение √(9x²)/x равно 3|x|/x=−3. Для x=0 оно не определено.','Корень из суммы не равен сумме корней. Сокращают множители, а не слагаемые. При нахождении синуса по косинусу требуется знак из четверти.')
topic(9,'f′(x₀) — угловой коэффициент касательной: Δy/Δx. Касательная y=f(x₀)+f′(x₀)(x−x₀). Если f′>0 на интервале, f возрастает; f′<0 — убывает. Смена знака +→− даёт максимум, −→+ минимум. Нулевая производная без смены знака не гарантирует экстремум.','График f: смотрите направление движения слева направо, не знак y. График f′: сравнивайте с осью Ox, не с ростом самого графика. Таблица знаков: найдите смены и принадлежность промежутку. Касательная: возьмите две точно заданные точки на прямой.','Касательная проходит через (1;5),(4;−1). f′(x₀)=(−1−5)/(4−1)=−2. Если f′ меняется в x=3 с минуса на плюс, x=3 — точка минимума.','Высота графика f не определяет знак f′. Концы отрезка при поиске наибольшего значения проверяют отдельно; точку экстремума не путайте со значением функции.')
topic(10,'Прикладная формула задаётся условием; важно сохранить единицы и физический диапазон. Примеры: S=v₀t+at²/2, v²=2al; P=UI; E=CU²/2; T=T₀·2^(−t/τ). Квадратное неравенство решается по знакам параболы, логарифмирование — только для положительных величин.','Сначала переведите единицы, затем выразите неизвестное. При двух корнях используйте ограничения процесса (до остановки, положительное время). Для «не менее» решите неравенство и выберите границу допустимого диапазона. В экспоненциальной модели выделите степень, затем логарифм.','S=20t−t², 0≤t≤10. При S=64 получаем t²−20t+64=0, t=4 или16. До остановки допустимо только 4 с.','Не выбирайте второй корень только потому, что он положительный. Не смешивайте км/ч и м/с. Округляйте лишь по прямому указанию.')
topic(11,'Движение: S=vt; средняя скорость — весь путь/всё время. Работа: объём=производительность·время, совместные производительности складываются. Растворы: масса вещества сохраняется при смешивании, испаряется только растворитель, если сказано именно это. Доли записываются десятичными числами.','Движение: таблица скорость–время–путь; на реке v±u. Работа: примите заказ за 1 и складывайте 1/t. Смесь: два баланса — общей массы и вещества. Проценты: отслеживайте базу процента. Выберите переменную с явным смыслом и областью допустимых значений.','Первый выполняет работу за 6 ч, второй за 12 ч. За час вместе 1/6+1/12=1/4 работы, значит время 4 ч.','Средняя скорость не среднее арифметическое скоростей при равных расстояниях. В задаче на проценты отмечайте, от какой массы/цены берётся процент. Проверяйте единицы.')
topic(12,'Прямая y=kx+b: k=(y₂−y₁)/(x₂−x₁). Парабола y=a(x−h)²+k с вершиной (h;k). Гипербола y=c/(x−h)+k с асимптотами x=h,y=k. Показательная y=aˣ: a>0,a≠1. Логарифмическая — обратная ей. Пересечения графиков находятся из равенства формул с общей ОДЗ.','По точкам восстановите коэффициенты; для параболы используйте вершину и ещё одну точку. По асимптотам сначала найдите сдвиги гиперболы. Пересечение: решите уравнение, исключите известный корень, если просят второй. Преобразования y=f(x−h)+k сдвигают вправо на h и вверх на k.','График y=a(x−2)²−3 проходит через (4;5). 5=4a−3 ⇒ a=2; f(0)=2·4−3=5.','В y=f(x−h) знак сдвига противоположен знаку внутри скобок. Не восстанавливайте график по неточному рисунку; нужны отмеченные точки. В дробной функции сохраняйте запрещённые x.')
topic(13,'Финансовая рекурсия: Dₖ=(1+r)Dₖ₋₁−Pₖ, если сначала начисляют проценты, затем платят. Равные погашения основного долга: D после платежей убывает на S/n; платежи Pₖ=S/n+rDₖ₋₁. Вклад со сложными процентами Sₙ=S₀(1+r)ⁿ.','Запишите порядок операций и долги по периодам. Для равного платежа разворачивайте рекурсию до Dₙ=0. Для равномерного уменьшения долга суммируйте проценты по арифметической прогрессии. При поиске ставки используйте общий платёж минус основной долг.','Кредит 100000 на 2 года под 10%, основной долг уменьшается по 50000. Платежи 60000 и55000; сумма115000. При равных общих платежах ответ был бы иным.','Равные платежи не означают равные погашения основного долга. Годовая ставка не применяется к исходной сумме каждый год при уменьшающемся долге. Соблюдайте рубли и тысячи рублей.')
topic(14,'Для тригонометрии: sin2x=2sinx cosx, cos2x=2cos²x−1; решения sin x=a: x=(−1)ⁿarcsin a+πn; cos x=a: x=±arccos a+2πn. При логарифмах аргументы положительны; знаменатели ненулевые. Замена t=aˣ требует t>0.','Часть а: ОДЗ, приведение к одной функции, замена/разложение на множители, полный набор серий. Не делите на функцию, которая может обращаться в ноль: выделите отдельный случай. Часть б: для каждой серии решите двойное неравенство относительно целого n; проверьте границы.','cos2x=cos x ⇒ 2c²−c−1=0 ⇒ c=1 или−1/2. Все корни: 2πn, ±2π/3+2πn. На [0;π] остаются 0 и2π/3.','Укажите n∈Z. Не ограничивайтесь численно найденными корнями. При возведении в квадрат проведите проверку, при отборе учитывайте оба конца отрезка.')
topic(15,'Прямая перпендикулярна плоскости, если перпендикулярна двум пересекающимся прямым этой плоскости. Угол прямой с плоскостью — угол с ортогональной проекцией. Двугранный угол измеряется линейным углом сечения, перпендикулярного ребру. В координатах расстояние до плоскости Ax+By+Cz+D=0 равно |Ax₀+By₀+Cz₀+D|/√(A²+B²+C²).','Доказательство: сформулируйте признак и покажите каждое условие. Угол: постройте проекцию или нормаль, затем найдите косинус. Расстояние: проведите общий перпендикуляр либо используйте нормаль; проверьте, что речь о прямой или именно отрезке. Объём/сечение: установите форму и размеры сечения.','В кубе ребра a плоскость x+y+z=a имеет нормаль(1,1,1); расстояние от O=(0,0,0) до неё a/√3. Формула следует из проекции радиус-вектора на единичную нормаль.','Не объявляйте угол между прямой и нормалью искомым углом прямой и плоскости: они дополняют друг друга до90°. Чертёж не доказывает перпендикулярность. Для координат объясните выбор осей.')
topic(16,'Неравенства: произведение/дробь решается методом интервалов с учётом кратностей. logₐu≥logₐv при a>1 равносильно u≥v на u,v>0; при0<a<1 знак меняется. aˣ>0. √u определён приu≥0; возводить обе части в квадрат равносильно, если они неотрицательны.','Выпишите ОДЗ отдельно. Соберите в одну дробь, разложите на множители, отметьте нули и полюса. В показательном используйте положительную замену t=aˣ. Модуль раскрывайте по точкам смены знака. В иррациональном разделяйте случаи по знаку второй части.','(x−1)/(x−3)≤0: точки1,3; знаки +,−,+. Числитель может равняться0, знаменатель нет; ответ[1;3).','Нельзя умножать на выражение неизвестного знака без разбора случаев. Не включайте запрещённые концы. Чётная кратность не меняет знак. После обратной замены пересеките с t>0.')
topic(17,'Моделирование: задайте переменные, ограничения и целевую функцию. Для гладкой функции на отрезке максимум/минимум ищут в критических точках и на концах. Производные: (xⁿ)′=nxⁿ⁻¹, (ln x)′=1/x, (eˣ)′=eˣ. Финансовая модель строится рекурсией долга; допустимые сроки/числа изделий могут быть целыми.','Геометрическая оптимизация: выразите площадь/объём через одну переменную с учётом материала. Производство: прибыль=выручка−затраты, найдите допустимый максимум. Дискретный выбор: после вещественного оптимума проверьте соседние целые. В кредите проверьте порядок процентов и платежей, затем оптимизируйте сумму.','Прямоугольник периметра40 имеет стороны x и20−x,0<x<20. S=20x−x²=100−(x−10)²≤100; максимум приx=10. Доказан глобальный максимум и допустимость размеров.','Стационарная точка может быть минимумом. Для открытого промежутка максимум может отсутствовать. Целочисленный оптимум требует отдельной проверки; недостаточно округлить автоматически.')
topic(18,'Планиметрия: подобие по двум углам/пропорциям, степени точки PA·PB=PC·PD; для касательной PT²=PA·PB. Цикличность: сумма противоположных углов180° или равные углы, опирающиеся на общий отрезок. Биссектриса BD/DC=AB/AC; медиана mₐ²=(2b²+2c²−a²)/4.','Часть а: укажите цепочку равенств углов/отношений и конкретный признак. Часть б: используйте доказанное для численного расчёта. Для касательных соедините точки касания с центром; для хорд примените степень точки. При координатах сначала обоснуйте расположение фигуры.','Из точкиP проведены касательнаяPT=6 и секущаяPAB, PA=4. По степени точки4·PB=36 ⇒ PB=9, AB=5. Важно, что порядок точек P,A,B.','Похожий рисунок не даёт подобия. Не путайте целую секущую с её внутренней частью. В доказательстве нельзя ссылаться на утверждение, которое требуется доказать.')
topic(19,'Параметр — фиксированное число, x — переменная. Число корней квадратного уравнения зависит от D и от условия ненулевого старшего коэффициента. Для |f(x)|=a необходимоa≥0; приa>0 решаютf=±a, приa=0 ветви совпадают. Замена t=g(x) требует знать область значений и число прообразов каждого t.','Разбейте ось параметра по особым значениям: обнуление коэффициента, касание, попадание корня на границу ОДЗ. Графический метод: количество пересечений с горизонталью и значения в экстремумах. Симметрия: считайте корни парами, отдельно x=0. Рациональные выражения: исключите общие нули числителя и знаменателя.','|x²−4|=a. Приa<0 корней нет; a=0 даёт2;0<a<4 даёт4; a=4 даёт3; a>4 даёт2. Приa=0 обе квадратные ветви одинаковы.','Не считайте кратность корня как несколько различных корней. Границы интервалов проверяйте отдельно. D>0 не гарантирует два допустимых корня после логарифмической или квадратной замены.')
topic(20,'Делимость: a≡b(mod m) означает m|(a−b). Для целых последовательностей полезны остатки, чётность, инварианты, оценки. Арифметическая прогрессия aₙ=a₁+(n−1)d, Sₙ=n(a₁+aₙ)/2. Положительные целые числа имеют дополнительные ограничения, которых нет у вещественных.','Пункт «может ли»: либо конструкция с проверкой всех условий, либо доказательство невозможности. Для экстремума сначала получите универсальную оценку, затем постройте пример равенства. При размене денег используйте сравнение по модулю и неотрицательность. В последовательности ищите инвариант операции.','Можно ли представить11 в виде3a+5b приa,b≥0 целых? По модулю3:2b≡2 ⇒ b≡1(mod3); b≤2 ⇒ b=1, a=2. Это даёт конструкцию11=3·2+5. Для7: b≤1, ни b=0, ниb=1 не подходят.','Перебор без ограничения диапазона не доказывает невозможность. Максимум без примера достижимости не установлен. В решении поясните, почему рассмотрены все остатки/случаи.')
pack(1,[
('Биссектриса и углы','В треугольнике ABC угол C равен 48°, AD — биссектриса угла A, угол BAD равен 27°. Найдите угол ADB в градусах.','105','∠A=54°, ∠B=180−54−48=78°. В треугольнике ABD угол при D равен180−27−78=75°? Угол ADB=75°.'),
('Средняя линия и площадь','Площадь треугольника ABC равна 96. Точки D и E — середины AC и BC. Найдите площадь трапеции ABED.','72','Треугольник CDE подобен CAB с коэффициентом1/2, его площадь96/4=24. Площадь трапеции96−24=72.'),
('Касательный четырёхугольник','В четырёхугольник ABCD вписана окружность. Его периметр30, сторона AB=9. Найдите CD.','6','У описанного четырёхугольника AB+CD равно полупериметру15. Поэтому CD=15−9=6.'),
('Биссектриса и стороны','В треугольнике ABC AB=10, AC=15, BC=20. Биссектриса AD пересекает BC в D. Найдите BD.','8','BD/DC=AB/AC=2/3. Всего5 долей составляют20, поэтому BD=20·2/5=8.'),
('Вписанный угол','Центральный угол AOB окружности равен 124°. Точка C лежит на большей дуге AB. Найдите угол ACB в градусах.','62','Угол ACB опирается на меньшую дугу AB величиной124°. Вписанный угол равен её половине:62°.'),
('Теорема косинусов','В треугольнике две стороны равны 5 и 8, угол между ними 60°. Найдите третью сторону.','7','c²=25+64−2·5·8·cos60°=89−40=49, c=7.'),
('Высота трапеции','Основания равнобедренной трапеции равны 10 и 22, боковая сторона10. Найдите площадь.','128','Проекция боковой стороны на большее основание равна(22−10)/2=6. Высота√(100−36)=8. S=(10+22)·8/2=128.'),
('Вписанная окружность','Стороны треугольника равны 13,14,15. Найдите радиус вписанной окружности.','4','p=21, по Герону S=√(21·8·7·6)=84. ИзS=pr следуетr=84/21=4.'),
('Касательные из точки','Из точки P проведены касательные PA и PB к окружности центра O. ∠APB=60°, OP=12. Найдите PA.','6√3','OA⊥PA; OP делит угол между касательными пополам. PA=OP·cos30°=6√3. Для числового ответа в данном задании требуется PA²=108.'),
('Диагонали ромба','Площадь ромба равна 120, одна диагональ равна 10. Найдите другую диагональ.','24','S=d₁d₂/2, значитd₂=2·120/10=24.')])
