# Пробелы вокруг границ математической записи и русского текста.
import re
for container in [T,Q]:
 for obj in container:
  for k in ('theory','prompt','answer','explanation'):
   if k not in obj:continue
   s=obj[k]
   s=re.sub(r'([а-яёА-ЯЁ])([0-9a-zA-ZαβφπΠ√∠Δ])',r'\1 \2',s)
   s=re.sub(r'([0-9a-zA-Zαβφπ])([а-яёА-ЯЁ])',r'\1 \2',s)
   obj[k]=s
