import json,re
p='data/math_exam_expanded.json';D=json.load(open(p));Q=D['questions']
def upd(n,i,**kw):
 q=next(x for x in Q if x['id']==f'math-full-2027-{n:02d}-{i}');q.update(kw)
 if 'explanation' in kw and n>=14:q['explanation']+='\n\nСамопроверка: обоснованы все утверждения пункта а), в вычислениях пункта б) учтены ограничения и положения точек; полный ответ совпадает с решением. Это учебный ориентир, а не официальная балльная шкала ФИПИ.'
for q in Q:
 if q['kind']=='self_check':q['prompt']=q['prompt'].replace(' В ответе запишите только одно число, без дополнительных пояснений.','')
 else:q['answer']=q['answer'].replace('−','-')
upd(14,5,prompt='а) Решите уравнение (sin2x−sin x)/sin x=0. б) Отберите все корни на отрезке[0;2π].',answer='а) x=±π/3+2πn, n∈Z. б) π/3,5π/3.',explanation='ОДЗ: sin x≠0, то есть x≠πk,k∈Z. На ОДЗ числитель равен sin x(2cos x−1), поэтому дробь равна0 тогда и только тогда, когда cos x=1/2. Получаем x=±π/3+2πn,n∈Z; их синусы не нулевые, поэтому все эти корни допустимы. Для π/3+2πn отбор по[0;2π] даёт −1/6≤n≤5/6, значит n=0. Для −π/3+2πn имеем1/6≤n≤7/6, значит n=1. Отобраны π/3,5π/3.')
upd(14,6,prototype='Сумма логарифмов с ограничением',prompt='а) Решите уравнение log₂(x−1)+log₂(x+1)=3+log₂(x−2). б) Отберите корни на отрезке[4;8].',answer='а) x=3,5. б)5.',explanation='ОДЗ: x−1>0,x+1>0,x−2>0, то есть x>2. Переносим последний логарифм: log₂((x²−1)/(x−2))=3. На ОДЗ это равносильно (x²−1)/(x−2)=8, откуда x²−8x+15=0. Разложение (x−3)(x−5)=0 даёт3 и5. Оба удовлетворяют x>2, поэтому оба являются корнями исходного уравнения. На отрезке[4;8] остаётся только5.')
upd(14,8,prototype='Два радикала и проверка квадратов',prompt='а) Решите уравнение √(x+6)+√(x−2)=4. б) Отберите корни на отрезке[2;4].',answer='а) x=3. б)3.',explanation='ОДЗ: x≥2. После первого квадрата получаем 2x+4+2√((x+6)(x−2))=16, то есть √((x+6)(x−2))=6−x. Теперь необходимо x≤6. При2≤x≤6 обе части неотрицательны, поэтому второй квадрат равносилен: x²+4x−12=x²−12x+36. Получаем16x=48,x=3. Проверка в исходном уравнении:√9+√1=4. Это единственный корень; он принадлежит[2;4].')
upd(6,1,prompt='Случайная величина X принимает значения0;2;5 с вероятностями0,2;0,5;0,3 соответственно. Найдите E(X).')
upd(6,2,prompt='Случайная величина X принимает значения−2;1;4 с вероятностями0,25;p;0,5 соответственно. Найдите математическое ожидание X.')
upd(18,2,prototype='Две высоты, окружность и ортоцентр',prompt='В остроугольном треугольнике ABC высоты AD и BE пересекаются в H (D∈BC,E∈AC). а) Докажите, что A,B,D,E лежат на одной окружности и CA·CE=CB·CD. б) Найдите AH, если AB=13,AC=14,BC=15.',answer='а) Окружность с диаметром AB; CA·CE=CB·CD. б) AH=25/4.',explanation='а) ∠ADB=∠AEB=90°, поэтому D и E лежат на окружности с диаметром AB. Точка C находится вне этой окружности: на луче CA точки идут C,E,A, а на луче CB — C,D,B. По степени точки C для двух секущих CA·CE=CB·CD. б) Введём A=(0;0),C=(14;0),B=(u;v),v>0. Из u²+v²=169 и(u−14)²+v²=225 получаем28u−196=−56, поэтомуu=5,v=12. Прямая BE вертикальна: x=5. Направление BC=(9;−12), поэтому высота из A имеет уравнение y=3x/4. Следовательно H=(5;15/4) и AH=√(25+225/16)=25/4. Положения D,E на сторонах обеспечиваются остроугольностью; найденный треугольник действительно остроугольный.')
upd(18,5,prototype='Касательная трапеция и диагонали',prompt='В равнобедренную трапецию с основаниями a>b вписана окружность радиуса r; высота трапеции h. Диагонали пересекаются в P, центр окружности O. а) Докажите h²=ab. б) Найдите OP, если r=3, а площадь трапеции60.',answer='а) h²=ab. б) OP=12/5.',explanation='а) По свойству описанного четырёхугольника сумма оснований равна сумме боковых сторон. Поэтому каждая боковая сторона l=(a+b)/2. Её горизонтальная проекция (a−b)/2, откуда по Пифагору h²=l²−((a−b)/2)²=((a+b)²−(a−b)²)/4=ab. б) Окружность касается обоих параллельных оснований, значит h=2r=6. Из площади (a+b)h/2=60 получаем a+b=20; из пункта а) ab=36. Так как a>b, основания a=18,b=2. Введём нижние вершины(−9;0),(9;0), верхние(−1;6),(1;6). По симметрии O=(0;3). Диагональ от(−9;0) к(1;6) пересекает ось x=0 при доле9/10 своей длины, поэтому P=(0;27/5). Получаем OP=27/5−3=12/5.')
upd(18,7,prototype='Хорда касания, диаметр и две длины',prompt='Окружность с центром O касается сторон угла с вершиной N в A и B. Отрезок BC — диаметр окружности. а) Докажите, что AC параллельна NO. б) Найдите NO, если AB>AC, AB+AC=14, а площадь треугольника ABC равна24.',answer='а) AC∥NO. б) NO=25/3.',explanation='а) OA=OB и NA=NB, поэтому O и N лежат на серединном перпендикуляре к AB и NO⊥AB. Вписанный угол BAC опирается на диаметр BC, значит AC⊥AB. Следовательно AC∥NO. б) Треугольник ABC прямоугольный при A. Пусть u=AB,v=AC; u+v=14,uv/2=24, то есть uv=48. Тогда u,v — корни t²−14t+48=0, равные8 и6. Условие AB>AC даёт AB=8,AC=6. Гипотенуза BC=10, радиус5. Если M — середина AB, то AM=4, OM=√(OA²−AM²)=3. Треугольник OAN прямоугольный при A, поскольку OA⊥NA, а AM — высота к гипотенузе ON. По теореме о квадрате катета OA²=OM·ON. Отсюда ON=25/3.')
upd(18,8,prototype='Середина дуги и центр вписанной окружности',prompt='В остроугольном треугольнике ABC центр вписанной окружности I, биссектриса AI пересекает описанную окружность вторично в E. а) Докажите EB=EC=EI. б) Найдите EI, если AB=13,AC=14,BC=15.',answer='а) EB=EC=EI. б) EI=5√13/2.',explanation='а) Обозначим углы треугольника A,B,C. Из ∠BAE=∠EAC следует равенство дуг BE и EC, не содержащих A; значит EB=EC. Точка E лежит на дуге BC по другую сторону BC относительно A, а I находится между A и E. Угол EBC равен EAC=A/2, угол IBC=B/2. Поэтому ∠IBE=(A+B)/2. Из ∠BIA=90°+C/2 получаем ∠BIE=180°−∠BIA=90°−C/2=(A+B)/2. В треугольнике BIE равны углы при B и I, значит EB=EI. б) Полупериметр21, по Герону площадь S=√(21·8·7·6)=84. Радиус описанной окружности R=13·14·15/(4·84)=65/8. По теореме косинусов cos A=(13²+14²−15²)/(2·13·14)=5/13. Поскольку A/2 острый, sin(A/2)=√((1−5/13)/2)=2/√13. Хорда EB опирается на угол BAE=A/2, поэтому EB=2R sin(A/2)=65/(2√13)=5√13/2. По пункту а) это EI.')
upd(18,10,prototype='Окружность через медиану и площадь',prompt='В треугольнике ABC точка M — середина BC. Окружность через A,B,M пересекает AC второй раз в D. Известно AB=13,AC=15,BC=14. а) Докажите, что D лежит внутри AC и CA·CD=CB·CM. б) Найдите площадь треугольника ABD.',answer='а) D∈AC; CA·CD=CB·CM. б) S(ABD)=3556/75.',explanation='а) На прямой CB точки расположены C,M,B. Степень C относительно окружности положительна и равна CM·CB=7·14=98, поэтому C вне окружности. Для секущей CA имеем CA·CD=98, откуда CD=98/15. Произведение положительно, значит второй конец секущей D находится на луче CA, а поскольку0<98/15<15, точка D лежит между C и A. б) AD=CA−CD=15−98/15=127/15. Полупериметр ABC равен21, площадь по Герону S=√(21·8·6·7)=84. Треугольники ABD и ABC имеют общую высоту из B на AC, поэтому S(ABD)/S(ABC)=AD/AC=127/225. Отсюда S(ABD)=84·127/225=3556/75.')
